use serde::Deserialize;

/// A file whose content was generated by the AI during the init interview.
#[derive(Debug, Clone, Deserialize)]
pub struct GeneratedFile {
    /// Relative path from project root (e.g. "CLAUDE.md", ".claude/rules/conventions.md").
    pub path: String,
    /// Full file content generated by the AI.
    pub content: String,
}
